     * @param repositories List of repository names (in the form `owner/repo-name`) to run the query
     *   against. Precisely one property from `repositories`, `repository_lists` and
     *   `repository_owners` is required.
     * @param repositoryLists List of repository lists to run the query against. Precisely one
     *   property from `repositories`, `repository_lists` and `repository_owners` is required.
     * @param repositoryOwners List of organization or user names whose repositories the query
     *   should be run against. Precisely one property from `repositories`, `repository_lists` and
     *   `repository_owners` is required.
     */
    fun codeScanningCreateVariantAnalysis(
        clientConfig: ClientConfig,
        request: CodeScanning.CodeScanningCreateVariantAnalysisRequest,
        options: RequestOptions? = null,
    ): CodeScanningVariantAnalysis {
