                            "query_pack" to (request.queryPack),
                            "repositories" to (SdkClient.omitIfNull(request.repositories)),
                            "repository_lists" to (SdkClient.omitIfNull(request.repositoryLists)),
                            "repository_owners" to (SdkClient.omitIfNull(request.repositoryOwners)),
                        ),
                    operationId = "codeScanningCreateVariantAnalysis",
