            )
            .data
    }

    private fun validateCodeScanningCreateVariantAnalysisRequest(
        request: CodeScanning.CodeScanningCreateVariantAnalysisRequest
    ) {
        if (request.repositoryLists != null) {
            Validation.validateItems(
                "repository_lists",
                request.repositoryLists,
                Validation.LengthOpts(max = 1),
            )
        }

        if (request.repositoryOwners != null) {
            Validation.validateItems(
                "repository_owners",
                request.repositoryOwners,
                Validation.LengthOpts(max = 1),
            )
        }
    }
