     *   parameter is not used, the tool name defaults to "API". If the uploaded SARIF contains a
     *   tool GUID, this will be available for filtering using the `tool_guid` parameter of
     *   operations such as `GET /repos/{owner}/{repo}/code-scanning/alerts`.
     * @param validate Whether the SARIF file will be validated according to the code scanning
     *   specifications. This parameter is intended to help integrators ensure that the uploaded
     *   SARIF files are correctly rendered by code scanning.
     */
    fun codeScanningUploadSarif(
        clientConfig: ClientConfig,
        request: CodeScanning.CodeScanningUploadSarifRequest,
        options: RequestOptions? = null,
    ): CodeScanningSarifsReceipt {
        validateCodeScanningUploadSarifRequest(request)

        return SdkClient.request<CodeScanningSarifsReceipt>(
                SdkClient.RequestSpec(
                    "POST",
                    "/repos/${SdkClient.encodePathSegment(request.owner)}/${SdkClient.encodePathSegment(request.repo)}/code-scanning/sarifs",
                    config = clientConfig,
                    body =
                        SdkClient.bodyMap(
                            "commit_sha" to (request.commitSha),
                            "ref" to (request.ref),
                            "sarif" to (request.sarif),
                            "checkout_uri" to (SdkClient.omitIfNull(request.checkoutUri)),
                            "started_at" to (SdkClient.omitIfNull(request.startedAt)),
                            "tool_name" to (SdkClient.omitIfNull(request.toolName)),
                            "validate" to (SdkClient.omitIfNull(request.validate)),
                        ),
                    operationId = "codeScanningUploadSarif",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                    errors =
                        mapOf(
                            "403" to BasicError::class.java,
                            "404" to BasicError::class.java,
                            "503" to ServiceUnavailable::class.java,
                        ),
                )
            )
            .data
    }

    private fun validateCodeScanningUploadSarifRequest(
        request: CodeScanning.CodeScanningUploadSarifRequest
    ) {
        Validation.validateLength(
            "commit_sha",
            request.commitSha,
            Validation.LengthOpts(min = 40, max = 64),
        )
        Validation.validatePattern(
            "commit_sha",
            request.commitSha,
            "^([0-9a-fA-F]{40}(?:[0-9a-fA-F]{24})?)$",
        )

        Validation.validatePattern("ref", request.ref, "^refs/(heads|tags|pull)/.*$")

        if (request.checkoutUri != null) {
            Validation.validateUri("checkout_uri", request.checkoutUri)
        }

        if (request.startedAt != null) {
            Validation.validateDateTime("started_at", request.startedAt)
        }
    }
}

